"""Apply the bespoke-portal fixes to an app generated by rebrand-thoughtspot-portal (<slug>-tse/).

Usage: python3 portal_finish.py <app-dir> --analytics-tab <tab guid> --inline-tab <tab guid>
                                --row-noun "departments" --premium-feature "Policy risk alerts & audit insights"

Idempotent. Applies, in one pass, every portal fix the Emburse pilot needed:
  1. Analytics embed shows only the analytics tab (activeTabId + visibleTabs) of the shared Liveboard.
  2. Inline-insights embed opens on the KPIs tab (activeTabId).
  3. Both embeds pass runtimeParameters [{ name: 'App Theme', value: light|dark }] so custom charts follow
     the app theme (the model must have the App Theme parameter; build_model_tml.py adds it).
  4. Dark-mode rules for table visualizations (DevExtreme + ag-Grid): only the header has a CSS variable,
     so without these, tables render white rows with dark text on dark tiles.
  5. Template copy that leaks the freight demo ("lane insights", "carriers shown here").
  7. Inline-metric formats: adds a 'percent' format (0.114 -> 11.4%); --currency swaps the hard-coded '$'.
  6. Brand gradient alias: the codemod renames var(--intime-grad) uses to var(--<slug>-grad) but the theme tokens still
     define --intime-grad, so the Premium tier pill (and other gradient accents) rendered with no background.
"""
import argparse
import os
import re
import sys

ap = argparse.ArgumentParser()
ap.add_argument("app")
ap.add_argument("--analytics-tab", required=True)
ap.add_argument("--inline-tab", required=True)
ap.add_argument("--row-noun", default=None, help="plural noun for the rows of the INLINE insights tab (e.g. reps, industries), used in its chatbot greeting; not the action-table rows. Omitted = leave as is")
ap.add_argument("--premium-feature", default="Priority insights & alerts")
ap.add_argument("--currency", default="$", help="symbol for currency-formatted inline metrics, e.g. £ or €")
a = ap.parse_args()
src = os.path.join(a.app, "src")
done = []


def edit(rel, fn):
    p = os.path.join(src, rel)
    s = open(p, encoding="utf-8").read()
    t = fn(s)
    if t != s:
        open(p, "w", encoding="utf-8").write(t)
        done.append(rel)


TABLE_DARK = """  // ---- Table visualizations (DevExtreme viz table + ag-Grid) [portal_finish] ----
  // Only the header background has a CSS variable; cells, rows, borders and hover keep light-mode
  // colours, so a dark tile shows white rows with dark text. Paint the grid onto the dark surface.
  [[
    '.dx-datagrid', '.dx-datagrid-headers', '.dx-datagrid-rowsview', '.dx-datagrid-content',
    '.dx-datagrid-table', '.dx-datagrid .dx-row', '.dx-datagrid .dx-row > td',
    '.dx-datagrid-total-footer', '.dx-datagrid-nodata',
    '.ag-root-wrapper', '.ag-root', '.ag-body-viewport', '.ag-center-cols-viewport',
    '.ag-center-cols-container', '.ag-row', '.ag-cell',
  ].join(',')]: { 'background-color': 'var(--pf-tbl-bg) !important', color: 'var(--pf-tbl-ink) !important', 'border-color': 'var(--pf-tbl-line) !important' },
  [[
    '.dx-datagrid-headers .dx-row > td', '.dx-header-row > td', '.dx-header-row td *',
    '.ag-header', '.ag-header-viewport', '.ag-header-row', '.ag-header-cell', '.ag-header-cell-text',
  ].join(',')]: { 'background-color': 'var(--pf-tbl-head) !important', color: 'var(--pf-tbl-head-ink) !important', 'border-color': 'var(--pf-tbl-line) !important' },
  [['.dx-datagrid .dx-row-alt > td', '.ag-row-odd'].join(',')]: { 'background-color': 'var(--pf-tbl-alt) !important' },
  [['.dx-datagrid .dx-row.dx-state-hover > td', '.dx-datagrid .dx-data-row:hover > td', '.ag-row-hover', '.ag-row:hover', '.ag-row:hover .ag-cell'].join(',')]: { 'background-color': 'var(--pf-tbl-hover) !important', color: '#ffffff !important' },
  [['.dx-datagrid .dx-selection > td', '.dx-datagrid .dx-row-focused > td', '.ag-row-selected', '.ag-row-selected .ag-cell'].join(',')]: { 'background-color': 'var(--pf-tbl-sel) !important', color: '#ffffff !important' },
  [['.dx-datagrid .dx-column-lines > td', '.ag-header-cell', '.ag-cell'].join(',')]: { 'border-color': 'var(--pf-tbl-line) !important' },
"""


def config(s):
    if "[portal_finish]" not in s:
        # Dark table palette: derived from the dark tile/border variables already in config.ts.
        tile = re.search(r"'--ts-var-liveboard-tile-background':\s*'(#[0-9a-fA-F]{6})'", s.split("TS_RULES_DARK")[0][::-1][::-1])
        darks = re.findall(r"'--ts-var-liveboard-tile-background':\s*'(#[0-9a-fA-F]{6})'", s)
        lines = re.findall(r"'--ts-var-liveboard-tile-border-color':\s*'(#[0-9a-fA-F]{6})'", s)
        heads = re.findall(r"'--ts-var-liveboard-tile-table-header-background':\s*'(#[0-9a-fA-F]{6})'", s)
        bg, line, head = (darks[-1] if darks else "#0a2546"), (lines[-1] if lines else "#1d3a60"), (heads[-1] if heads else "#0b2648")
        pal = {"--pf-tbl-bg": bg, "--pf-tbl-ink": "#e7ecf2", "--pf-tbl-line": line, "--pf-tbl-head": head, "--pf-tbl-head-ink": "#c3cbd6",
               "--pf-tbl-alt": head, "--pf-tbl-hover": line, "--pf-tbl-sel": "rgba(77, 163, 236, 0.35)"}
        rules = TABLE_DARK
        for k, v in pal.items():
            rules = rules.replace("var(" + k + ")", v)
        s = s.replace("export const TS_RULES_DARK: Record<string, Record<string, string>> = {\n",
                      "export const TS_RULES_DARK: Record<string, Record<string, string>> = {\n" + rules, 1)
    if "ANALYTICS_TAB_ID" not in s:
        s += ("\n/** Liveboard tabs: Analytics shows only its tab; inline insights open on the KPIs tab. [portal_finish] */\n"
              "export const ANALYTICS_TAB_ID = '" + a.analytics_tab + "';\n"
              "export const INLINE_INSIGHTS_TAB_ID = '" + a.inline_tab + "';\n")
    if "themeParameters" not in s:
        s += ("\n/** Model parameter the custom charts read to match the app's light/dark theme. [portal_finish] */\n"
              "export const THEME_PARAMETER = 'App Theme';\n"
              "export const themeParameters = (theme: string) => [{ name: THEME_PARAMETER, value: theme === 'dark' ? 'dark' : 'light' }];\n")
    if a.row_noun:
        s = re.sub(r"'What would you like to know about the [a-z ]+ shown here\?'", "'What would you like to know about the " + a.row_noun + " shown here?'", s)
    return s


def add_import(s, names):
    for n in names:
        if re.search(r"\b" + n + r",", s.split("from '../config'")[0]):
            continue
        s = re.sub(r"(\n\} from '\.\./config';)", "\n  " + n + "," + r"\1", s, count=1)
    return s


def analytics(s):
    if "visibleTabs={[ANALYTICS_TAB_ID]}" not in s:
        s = s.replace("              liveboardId={ANALYTICS_LIVEBOARD_ID}\n",
                      "              liveboardId={ANALYTICS_LIVEBOARD_ID}\n              activeTabId={ANALYTICS_TAB_ID}\n"
                      "              visibleTabs={[ANALYTICS_TAB_ID]}\n              runtimeParameters={themeParameters(theme)}\n", 1)
    return add_import(s, ["ANALYTICS_TAB_ID", "themeParameters"])


def inline(s):
    if "activeTabId={INLINE_INSIGHTS_TAB_ID}" not in s:
        s = s.replace("                          liveboardId={INLINE_INSIGHTS_LIVEBOARD_ID}\n",
                      "                          liveboardId={INLINE_INSIGHTS_LIVEBOARD_ID}\n                          activeTabId={INLINE_INSIGHTS_TAB_ID}\n"
                      "                          runtimeParameters={themeParameters(theme)}\n", 1)
    return add_import(s, ["INLINE_INSIGHTS_TAB_ID", "themeParameters"])


edit("config.ts", config)
edit("tabs/Analytics.tsx", analytics)
edit("tabs/Carriers.tsx", inline)
def grad_alias(s):
    used = set(re.findall(r"var\((--[a-z0-9-]+-grad)\)", s))
    undefined = sorted(v for v in used if v != "--intime-grad" and not re.search(re.escape(v) + r"\s*:", s))
    if not undefined:
        return s
    return s + "\n/* [portal_finish] brand gradient alias */\n:root { " + " ".join(v + ": var(--intime-grad);" for v in undefined) + " }\n"


def metric_formats(s):
    if "format === 'percent'" not in s:
        s = s.replace("  if (format === 'currency') {", "  if (format === 'percent') {\n    return Number.isNaN(num) ? raw : `${(num * 100).toFixed(1)}%`;\n  }\n  if (format === 'currency') {", 1)
    return s.replace("format: 'text' | 'date' | 'number' | 'currency';", "format: 'text' | 'date' | 'number' | 'currency' | 'percent';")


edit("styles/globals.css", grad_alias)
edit("lib/thoughtspot.ts", metric_formats)
edit("config.ts", lambda s: s.replace("format: 'text' | 'date' | 'number' | 'currency';", "format: 'text' | 'date' | 'number' | 'currency' | 'percent';"))
edit("components/TrialModal.tsx", lambda s: s.replace("'Priority capacity & lane insights',", "'" + a.premium_feature.replace("'", "\\'") + "',"))

missing = []
for rel, needle in (("tabs/Analytics.tsx", "visibleTabs={[ANALYTICS_TAB_ID]}"), ("tabs/Carriers.tsx", "activeTabId={INLINE_INSIGHTS_TAB_ID}"), ("config.ts", "[portal_finish]")):
    if needle not in open(os.path.join(src, rel), encoding="utf-8").read():
        missing.append(rel + " (anchor not found; template changed? apply by hand)")
# Inline-metric money formatter ships with a hardcoded "$" (HMR run): use the dataset's currency.
if a.currency != "$":
    edit("lib/thoughtspot.ts", lambda s: re.sub(r"`\$\$\{", "`" + a.currency + "${", s))

# chatbot.ts FAQ entries link to <Client>_DOCS.<key>. A key missing from the DOCS map puts `undefined` in an answer's
# links and the Ask tab crashes (blank app) the first time that answer renders (Lineal/Moxie: DOCS.help). Add any
# missing key, pointing at the DOCS `contact` (or `home`) entry.
def docs_keys(s):
    m = re.search(r"export const (\w+_DOCS): Record<string, DocLink> = \{(.*?)\n\};?", s, re.S)
    if not m:
        return s
    name, body = m.group(1), m.group(2)
    have = set(re.findall(r"^\s*(\w+):", body, re.M))
    missing = sorted(set(re.findall(re.escape(name) + r"\.(\w+)", s)) - have)
    if not missing:
        return s
    fallback = "contact" if "contact" in have else ("help" if "help" in have else "home")
    lines = "".join("  %s: %s.%s,\n" % (k, name, fallback) for k in missing)
    print("chatbot.ts: added missing %s keys %s -> %s" % (name, missing, fallback))
    return s.replace(m.group(0), m.group(0) + "\n// [portal_finish] keys the FAQ uses but the map lacked\nObject.assign(" + name + ", {\n" + lines + "});", 1)


if os.path.exists(os.path.join(src, "lib", "chatbot.ts")):
    edit("lib/chatbot.ts", docs_keys)

print("patched:", ", ".join(done) or "nothing (already applied)")
if missing:
    print("NOT APPLIED:\n- " + "\n- ".join(missing))
    sys.exit(1)
